<?php

declare(strict_types=1);

namespace Modules\Catalog\Core\UseCases;

use Illuminate\Database\Eloquent\ModelNotFoundException;
use Illuminate\Support\Facades\DB;
use Modules\Catalog\Core\DTOs\CategoryDTO;
use Modules\Catalog\Events\CategoryUpdated;
use Modules\Catalog\Persistence\Models\Category;
use Modules\Catalog\Persistence\Repositories\CategoryRepository;
use Modules\Messaging\Contracts\EventOutbox;

/**
 * Admin: renames a category (the slug is regenerated by the model). The row is locked before the new version is
 * computed, and catalog.category_updated is recorded in the same transaction.
 */
final class UpdateCategoryUseCase
{
    public function __construct(
        private readonly CategoryRepository $categories,
        private readonly EventOutbox $outbox,
    ) {}

    /**
     * @throws ModelNotFoundException
     */
    public function execute(string $categoryId, CategoryDTO $data): Category
    {
        $category = DB::transaction(function () use ($categoryId, $data): Category {
            $category = $this->categories->lockById($categoryId);

            $this->categories->update($category, [...$data->toArray(), 'version' => $category->version + 1]);

            $this->outbox->record(new CategoryUpdated($category->id, $category->name, $category->slug, $category->version));

            return $category;
        });

        return $category->loadCount('products');
    }
}
